function run() {
    logPipeline("started");

    let runState = {};
    if (fs.existsSync('../run_state.json')) {
        runState = JSON.parse(fs.readFileSync('../run_state.json', 'utf8'));
        if (runState.reachability && runState.reachability.stage_failed === false && runState.reachability.cves) {
            logPipeline("stage already completed successfully. Skipping.");
            return;
        }
    }

    const advisories = JSON.parse(fs.readFileSync('advisories.json', 'utf8'));

    const excludeDirs = ['node_modules', 'test', 'dist', 'build', '.git'];
    const jsFiles = [];

    function findJsFiles(dir) {
        if (excludeDirs.includes(path.basename(dir))) return;
        const entries = fs.readdirSync(dir, { withFileTypes: true });
        for (const entry of entries) {
            const fullPath = path.join(dir, entry.name);
            if (entry.isDirectory()) {
                if (!excludeDirs.includes(entry.name)) {
                    findJsFiles(fullPath);
                }
            } else if (entry.name.endsWith('.js')) {
                jsFiles.push(fullPath);
            }
        }
    }
    findJsFiles('.');

    const imports = {}; // varName -> { pkgName, isDynamic }
    const usages = {};  // varName -> array of usage locations

    let crawlIncomplete = false;
    const startTime = Date.now();

    for (const file of jsFiles) {
        if (Date.now() - startTime > 30000) {
            crawlIncomplete = true;
            logPipeline("Crawl timeout exceeded 30s. Results incomplete.");
            break;
        }

        try {
            const code = fs.readFileSync(file, 'utf8');
            const ast = acorn.parse(code, { ecmaVersion: 2020, allowHashBang: true, sourceType: 'module' });

            // Pass 1: Find requires and imports
            walk.simple(ast, {
                VariableDeclarator(node) {
                    if (node.init && node.init.type === 'CallExpression' && 
                        node.init.callee.name === 'require' && 
                        node.init.arguments.length > 0) {
                        const pkgName = node.init.arguments[0].value;
                        const varName = node.id && node.id.name;
                        if (varName) {
                            imports[varName] = { pkgName, isDynamic: false };
                            if (!usages[varName]) usages[varName] = [];
                        } else if (node.id && node.id.type === 'ObjectPattern') {
                            imports['__destructured_' + pkgName] = { pkgName, isDynamic: true };
                        }
                    }
                    if (node.init && node.init.type === 'MemberExpression' &&
                        node.init.object.type === 'CallExpression' &&
                        node.init.object.callee.name === 'require' &&
                        node.init.object.arguments.length > 0) {
                        const pkgName = node.init.object.arguments[0].value;
                        const varName = node.id && node.id.name;
                        if (varName) {
                            imports[varName] = { pkgName, isDynamic: true };
                            if (!usages[varName]) usages[varName] = [];
                        }
                    }
                },
                ImportDeclaration(node) {
                    if (node.source && node.source.value) {
                        const pkgName = node.source.value;
                        for (const spec of node.specifiers) {
                            if (spec.local && spec.local.name) {
                                imports[spec.local.name] = { pkgName, isDynamic: false };
                                if (!usages[spec.local.name]) usages[spec.local.name] = [];
                            }
                        }
                    }
                }
            });

            // Pass 2: Find usages
            walk.simple(ast, {
                MemberExpression(node) {
                    if (node.object.type === 'Identifier' && usages[node.object.name] !== undefined) {
                        usages[node.object.name].push(`property access in ${file}`);
                    }
                },
                CallExpression(node) {
                    if (node.callee.type === 'Identifier' && usages[node.callee.name] !== undefined) {
                        usages[node.callee.name].push(`function call in ${file}`);
                    }
                }
            });
        } catch (e) {
            // Ignore parse errors on individual files
        }
    }

    const reachabilityCves = [];
    let reachableCount = 0;
    let uncertainCount = 0;

    for (const vuln of advisories) {
        let verdict = "NOT_REACHABLE";
        let evidence = "Package is not imported in scanned source files.";

        let importedAs = null;
        let isDynamic = false;

        for (const [varName, info] of Object.entries(imports)) {
            if (info.pkgName === vuln.package) {
                importedAs = varName;
                isDynamic = info.isDynamic;
                break;
            }
        }

        if (importedAs) {
            if (isDynamic) {
                verdict = "reachability_uncertain";
                evidence = `Dynamically/aliased/destructured import detected, reachability uncertain.`;
                uncertainCount++;
            } else if (usages[importedAs] && usages[importedAs].length > 0) {
                verdict = "REACHABLE";
                evidence = `Imported as ${importedAs} and used (${usages[importedAs].slice(0,2).join(', ')}...)`;
                reachableCount++;
            } else {
                evidence = `Package imported as '${importedAs}' but never invoked.`;
            }
        }

        reachabilityCves.push({
            cve_id: vuln.cve_id,
            package: vuln.package,
            verdict: verdict,
            evidence: evidence
        });
    }

    const reachabilityData = { cves: reachabilityCves, crawl_incomplete: crawlIncomplete, stage_failed: false, error: "" };
    fs.writeFileSync('reachability.json', JSON.stringify(reachabilityData, null, 2));

    runState = {};
    if (fs.existsSync('../run_state.json')) {
        runState = JSON.parse(fs.readFileSync('../run_state.json', 'utf8'));
    }
    runState.reachability = reachabilityData;
    runState.timestamps = runState.timestamps || {};
    runState.timestamps.reachability_completed_at = new Date().toISOString();
    fs.writeFileSync('../run_state.json', JSON.stringify(runState, null, 2));

    logPipeline(`complete. ${reachabilityCves.length} CVEs: ${reachableCount} REACHABLE, ${uncertainCount} UNCERTAIN.`);
}

async function run() {
    logPipeline("started");

    let runState = {};
    if (fs.existsSync('../run_state.json')) {
        runState = JSON.parse(fs.readFileSync('../run_state.json', 'utf8'));
        if (runState.scanner && runState.scanner.stage_failed === false && runState.scanner.detected_cves) {
            logPipeline("stage already completed successfully. Skipping.");
            return;
        }
    }

    const lockfileData = JSON.parse(fs.readFileSync('package-lock.json', 'utf8'));
    const packagesToScan = new Map();
    function addPackage(name, version) {
        if (!packagesToScan.has(name)) {
            packagesToScan.set(name, version);
        }
    }

    const rootDeps = lockfileData.packages[""]?.dependencies || {};
    for (const depName of Object.keys(rootDeps)) {
        const pkgPath = `node_modules/${depName}`;
        const pkgData = lockfileData.packages[pkgPath];
        if (pkgData) {
            addPackage(depName, pkgData.version);
            const transDeps = pkgData.dependencies || {};
            for (const transName of Object.keys(transDeps)) {
                let transPkg = lockfileData.packages[`node_modules/${depName}/node_modules/${transName}`] 
                            || lockfileData.packages[`node_modules/${transName}`];
                if (transPkg) {
                    addPackage(transName, transPkg.version);
                }
            }
        }
    }

    const packagesList = Array.from(packagesToScan.entries());
    if (packagesList.length === 0) {
        logPipeline("No dependencies found to scan.");
        return;
    }

    const detected_cves = [];
    const failed_packages = [];
    const uniqueCves = new Map();

    async function fetchOsv(name, version) {
        const postData = JSON.stringify({
            package: { name: name, ecosystem: 'npm' },
            version: version
        });

        for (let attempt = 1; attempt <= 3; attempt++) {
            try {
                const result = await new Promise((resolve, reject) => {
                    const options = {
                        hostname: 'api.osv.dev',
                        port: 443,
                        path: '/v1/query',
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Content-Length': Buffer.byteLength(postData)
                        },
                        timeout: 5000
                    };
                    const req = https.request(options, (res) => {
                        if (res.statusCode === 429 || res.statusCode >= 500) {
                            reject(new Error(`HTTP ${res.statusCode}`));
                            return;
                        }
                        let data = '';
                        res.on('data', (chunk) => { data += chunk; });
                        res.on('end', () => resolve(JSON.parse(data)));
                    });
                    req.on('timeout', () => {
                        req.destroy();
                        reject(new Error('timeout'));
                    });
                    req.on('error', (e) => reject(e));
                    req.write(postData);
                    req.end();
                });
                return result;
            } catch (err) {
                if (attempt === 3) throw err;
                await new Promise(r => setTimeout(r, Math.pow(2, attempt) * 100));
            }
        }
    }

    const BATCH_SIZE = 10;
    for (let i = 0; i < packagesList.length; i += BATCH_SIZE) {
        const batch = packagesList.slice(i, i + BATCH_SIZE);
        await Promise.all(batch.map(async ([name, version]) => {
            try {
                const result = await fetchOsv(name, version);
                if (result.vulns && result.vulns.length > 0) {
                    for (const vuln of result.vulns) {
                        const cve = vuln.aliases ? vuln.aliases.find(a => a.startsWith('CVE-')) : vuln.id;
                        const cve_id = cve || vuln.id;

                        let severity = "UNKNOWN";
                        if (vuln.severity && vuln.severity.length > 0) {
                            severity = vuln.severity[0].score;
                        } else if (vuln.database_specific && vuln.database_specific.severity) {
                            severity = vuln.database_specific.severity;
                        }

                        let fixed_version = null;
                        if (vuln.affected && vuln.affected.length > 0) {
                            const affected = vuln.affected[0];
                            if (affected.ranges && affected.ranges.length > 0) {
                                const range = affected.ranges[0];
                                for (const event of range.events) {
                                    if (event.fixed) {
                                        fixed_version = event.fixed;
                                    }
                                }
                            }
                        }
                        const key = `${name}-${cve_id}`;
                        if (!uniqueCves.has(key)) {
                            uniqueCves.set(key, {
                                package: name,
                                version: version,
                                cve_id: cve_id,
                                severity: severity,
                                fixed_version: fixed_version || 'unknown',
                                affected_range: 'unknown',
                                source: 'OSV'
                            });
                        }
                    }
                }
            } catch (e) {
                console.error(`Error querying ${name}: ${e.message}`);
                failed_packages.push(name);
            }
        }));
    }

    detected_cves.push(...uniqueCves.values());

    runState = {};
    if (fs.existsSync('../run_state.json')) {
        runState = JSON.parse(fs.readFileSync('../run_state.json', 'utf8'));
    }
    runState.scanner = { 
        detected_cves, 
        failed_packages, 
        stage_failed: false,
        error: ""
    };

    fs.writeFileSync('advisories.json', JSON.stringify(detected_cves, null, 2));
    runState.timestamps = runState.timestamps || {};
    runState.timestamps.started_at = new Date().toISOString();
    runState.timestamps.scan_completed_at = new Date().toISOString();
    fs.writeFileSync('../run_state.json', JSON.stringify(runState, null, 2));

    logPipeline(`${packagesList.length} packages checked, ${detected_cves.length} CVEs found, ${failed_packages.length} scan failures`);
}

